            logger.warning("model call returned HTTP %s", response.status_code)
            return ModelResult(
                facts=parse_facts(None),
                warnings=[
                    f"Model call returned HTTP {response.status_code}; cautious path applied"
                ],
            )

        try:
            envelope = response.json()
        except ValueError:
