        if any(r.code == "refers_to_previous_work" for r in decision.reasons):
            # Not a hazard: a coordinator is reviewing the earlier work on this equipment.
            lines = [
                OPENING,
                f"You asked us to look at the earlier work on {equipment}{site}"
                + (f" in connection with {issue}." if issue else "."),
                "A coordinator is reviewing the previous visits for this equipment before "
                "we arrange anything further, so that we build on what was already done "
                "rather than duplicating it.",
                "We will come back to you with the next step shortly.",
            ]
            return " ".join(lines)

        reported = decision.safetyQuote.strip()
        quoted = f' You reported: "{reported}"' if reported else ""
        return " ".join(
            [
                OPENING,
                f"We have treated your report about {equipment}{site} as a possible safety"
                f" issue.{quoted}",
                "Please keep people away from the equipment and do not attempt to operate "
                "or investigate it.",
                "This has been escalated to our duty team, who will contact you directly.",
            ]
        )

    # --- clarification: the one safety question, or only what we need ---
    if status == "clarification_required":
        if decision.safetyQuestion:
            return " ".join(
                [
                    OPENING,
                    f"Before we arrange anything for {equipment}{site}, we need to check one "
                    "thing.",
                    decision.safetyQuestion,
                    "Please reply to this message and we will continue as soon as we hear "
                    "from you.",
                ]
            )

        needed = decision.missingInformation
        ask = needed[0] if needed else "a little more detail about the equipment involved"
        acknowledgement = (
            f"We have your report of {issue}{site}." if issue else "We have your request."
        )
        return " ".join(
            [
                OPENING,
                acknowledgement,
                f"Before we can decide the next step, could you confirm: {ask.rstrip('.').lower()}?",
                "As soon as we have that we will take this forward.",
            ]
        )

    # --- account review: acknowledge, no promise of attendance ----------
    if status == "account_review_required":
        acknowledgement = (
            f"We have your report of {issue} on {equipment}{site}."
            if issue
            else f"We have your request about {equipment}{site}."
        )
