"""Customer reply drafts.

One template per status, filled with the customer's own problem description, the
equipment, the contract response window and any references, so every reply is about
their actual issue rather than a generic acknowledgement.

Rules taken from the policies:
- Safety escalation says to keep people away and that it is with the duty team. No
  diagnosis, no troubleshooting, no advice of any kind (POL-SAFETY-001).
- A safety clarification carries one plain question and nothing else.
- Other clarifications ask only for what changes the next action (OPS-INTAKE-003).
- Account review acknowledges the problem and says the account record is being checked,
  without promising attendance (POL-CONTRACT-002).
- Planned work names the service and equipment and says it is being scheduled under the
  contract, with no date (our D2: no scheduling lead-time data).
- A duplicate says it is linked to the existing request, with the reference.
- Dispatch states the response window, and only claims a technician once the work order
  actually exists (OPS-INTAKE-003: never imply a technician is confirmed before the
  work-order response has been reconciled).
- Resource escalation acknowledges without promising a time.
- Failure says a coordinator is reviewing it, with no raw error text.

Nothing here exposes internal notes, confidence scores, policy ids or system errors.
"""

from __future__ import annotations

from typing import Any

from .decide import Decision
from .evidence import AssetEvidence
from .facts import RequestFacts

OPENING = "Thank you for contacting Northstar Field Services."


def _equipment_phrase(evidence: AssetEvidence) -> str:
    """How to name the equipment to the customer: nickname and id where we have them."""
    if not evidence.asset:
        return "the equipment you reported"
    nickname = evidence.asset.get("nickname")
    asset_id = evidence.assetId
    if nickname and asset_id:
        return f"{nickname} ({asset_id})"
    if nickname:
        return str(nickname)
    if asset_id:
        return str(asset_id)
    return "the equipment you reported"


def _issue_phrase(facts: RequestFacts) -> str:
    """The customer's own description of the problem, lightly tidied."""
    summary = (facts.symptomSummary or "").strip().rstrip(".")
    if not summary:
        return ""
    return summary[0].lower() + summary[1:] if summary[:1].isupper() else summary


def _site_phrase(evidence: AssetEvidence) -> str:
    site = (evidence.site or {}).get("name")
    return f" at {site}" if site else ""


def _response_window(evidence: AssetEvidence) -> str | None:
    agreement = evidence.agreement or {}
    hours = agreement.get("responseHours")
    return f"{hours} hours" if hours else None


def build_customer_reply(
    facts: RequestFacts,
    evidence: AssetEvidence,
    decision: Decision,
    work_order: dict[str, Any] | None = None,
) -> str:
    """One reply, in the customer's terms, for the status we reached."""
    equipment = _equipment_phrase(evidence)
    issue = _issue_phrase(facts)
    site = _site_phrase(evidence)
    status = decision.status

    # --- safety: no advice, no diagnosis, no troubleshooting ------------
    if status == "human_escalation_required":
        if any(r.code == "refers_to_previous_work" for r in decision.reasons):
            # Not a hazard: a coordinator is reviewing the earlier work on this equipment.
            lines = [
                OPENING,
                f"You asked us to look at the earlier work on {equipment}{site}"
                + (f" in connection with {issue}." if issue else "."),
                "A coordinator is reviewing the previous visits for this equipment before "
                "we arrange anything further, so that we build on what was already done "
                "rather than duplicating it.",
                "We will come back to you with the next step shortly.",
            ]
            return " ".join(lines)

        reported = decision.safetyQuote.strip()
        quoted = f' You reported: "{reported}"' if reported else ""
        return " ".join(
            [
                OPENING,
                f"We have treated your report about {equipment}{site} as a possible safety"
                f" issue.{quoted}",
                "Please keep people away from the equipment and do not attempt to operate "
                "or investigate it.",
                "This has been escalated to our duty team, who will contact you directly.",
            ]
        )

    # --- clarification: the one safety question, or only what we need ---
    if status == "clarification_required":
        if decision.safetyQuestion:
            return " ".join(
                [
                    OPENING,
                    f"Before we arrange anything for {equipment}{site}, we need to check one "
                    "thing.",
                    decision.safetyQuestion,
                    "Please reply to this message and we will continue as soon as we hear "
                    "from you.",
                ]
            )

        needed = decision.missingInformation
        ask = needed[0] if needed else "a little more detail about the equipment involved"
        acknowledgement = (
            f"We have your report of {issue}{site}." if issue else "We have your request."
        )
        return " ".join(
            [
                OPENING,
                acknowledgement,
                f"Before we can decide the next step, could you confirm: {ask.rstrip('.').lower()}?",
                "As soon as we have that we will take this forward.",
            ]
        )

    # --- account review: acknowledge, no promise of attendance ----------
    if status == "account_review_required":
        acknowledgement = (
            f"We have your report of {issue} on {equipment}{site}."
            if issue
            else f"We have your request about {equipment}{site}."
        )
        return " ".join(
            [
                OPENING,
                acknowledgement,
                "Before we can confirm what happens next, we are checking the service "
                "agreement record for this equipment.",
                "We will come back to you as soon as that check is complete.",
            ]
        )

    # --- duplicate: linked to the existing request ----------------------
    if status == "duplicate_detected":
        references = decision.linkedWorkOrders + decision.linkedRequests
        reference_text = (
            f" under reference {', '.join(references)}" if references else ""
        )
        return " ".join(
            [
                OPENING,
                f"This relates to a request we already have open for {equipment}{site}"
                f"{reference_text}.",
                "We have linked your message to that existing job rather than raising a "
                "second one, so everything stays in one place.",
                "The team handling it will keep you updated.",
            ]
        )

    # --- dispatch: only claim a technician if the job really exists -----
    if status == "dispatch_ready":
        window = _response_window(evidence)
        reported = f"We have your report of {issue} on {equipment}{site}." if issue else (
            f"We have your report about {equipment}{site}."
        )
        if work_order:
            lines = [OPENING, reported, "An engineer has been assigned to attend."]
            if window:
                lines.append(
                    f"Under your service agreement we will be with you within {window}."
                )
            lines.append("We will confirm the visit details shortly.")
            return " ".join(lines)

        # No work order: do not imply anyone is confirmed.
        lines = [OPENING, reported, "We are arranging an engineer to attend."]
        if window:
            lines.append(f"Your service agreement provides a response within {window}.")
        lines.append("We will confirm the details as soon as the visit is booked.")
        return " ".join(lines)

    # --- resource escalation: acknowledge, no time promise --------------
    if status == "resource_escalation_required":
        reported = (
            f"We have your report of {issue} on {equipment}{site}."
            if issue
            else f"We have your request about {equipment}{site}."
        )
        return " ".join(
            [
                OPENING,
                reported,
                "This needs an engineer with specific qualifications for your equipment, "
                "and our dispatch team is arranging that now.",
                "We will contact you with the arrangements as soon as they are confirmed.",
            ]
        )

    # --- covered planned work: named, scheduled, no date ----------------
    if status == "covered_action":
        contract = (evidence.agreement or {}).get("contractRef")
        contract_text = f" under agreement {contract}" if contract else " under your service agreement"
        if facts.intent == "coverage_question":
            window = _response_window(evidence)
            lines = [
                OPENING,
                f"We can confirm that {equipment}{site} is covered{contract_text}.",
            ]
            if window:
                lines.append(f"It carries a response commitment of {window}.")
            lines.append("Please let us know if you would like us to arrange a visit.")
            return " ".join(lines)

        service = issue or "the service you requested"
        return " ".join(
            [
                OPENING,
                f"We have your request for {service} on {equipment}{site}.",
                f"This is covered{contract_text}, and we are scheduling the visit now.",
                "We will come back to you shortly to agree a date and time.",
            ]
        )

    # --- failure: a coordinator has it, no raw errors -------------------
    if status == "failed":
        reported = (
            f"We have your report of {issue} on {equipment}{site}."
            if issue
            else "We have received your request."
        )
        return " ".join(
            [
                OPENING,
                reported,
                "A coordinator is reviewing it personally and will come back to you shortly.",
            ]
        )

    return " ".join(
        [OPENING, "A coordinator is reviewing your request and will come back to you shortly."]
    )

